}

variable "environment" {
  description = "Target Deployment Environment"
  type        = string
  default     = "production"
}

variable "vpc_cidr" {
  description = "CIDR block for the target VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "db_password" {
  description = "Database Master Password (Sensitive - supply via TF_VAR_db_password or Secrets Manager)"
  type        = string
  sensitive   = true
  default     = null
}

variable "ami_id" {
  description = "Target AMI ID for the imported operating system image (optional; overrides default imported AMI)"
  type        = string
  default     = ""
}

files.main.tf:
# ============================================================
# AUTOMATICALLY GENERATED BY CLOUDMOVE MIGRATION ENGINE
# MAIN INFRASTRUCTURE MODULE
# ============================================================

# Dynamic secure credentials generation (zero hardcoded secrets)
resource "random_password" "db_master_password" {
  length  = 24
  special = false
}

locals {
  effective_db_password = var.db_password != null && var.db_password != "" ? var.db_password : random_password.db_master_password.result
}

# Network & Isolation Boundaries
resource "aws_vpc" "target_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = "cloudmove-target-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.target_vpc.id
  tags = {
    Name = "cloudmove-igw"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.target_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = "cloudmove-public-subnet"
  }
}

resource "aws_subnet" "private_subnet_a" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "cloudmove-private-subnet-a"
  }
}

resource "aws_subnet" "private_subnet_b" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "${var.aws_region}b"
  tags = {
    Name = "cloudmove-private-subnet-b"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "cloudmove-app-sg"
  description = "Security group for migrated application workloads"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-app-sg"
  }
}

# Migrated Resource: rabbitmq-kali-live-os (img-live-rabbitmq-kali)
resource "aws_ebs_snapshot_import" "img_live_rabbitmq_kali_import" {
  disk_container {
    description = "Imported disk image for rabbitmq-kali-live-os"
    format      = "RAW"
    user_bucket {
      s3_bucket = "cloudmove-vm-import-staging"
      s3_key    = "images/rabbitmq-kali-live-os.vmdk"
    }
  }
  role_name = "vmimport"
  tags = {
    Name      = "rabbitmq-kali-live-os-snapshot"
    CMIR_ID   = "img-live-rabbitmq-kali"
    ManagedBy = "CloudMove"
  }
}

resource "aws_ami" "img_live_rabbitmq_kali" {
  name                = "rabbitmq-kali-live-os-ami"
  virtualization_type = "hvm"
  architecture        = "x86_64"
  boot_mode           = "uefi"
  root_device_name    = "/dev/sda1"
  ena_support         = true
  ebs_block_device {
    device_name = "/dev/sda1"
    snapshot_id = aws_ebs_snapshot_import.img_live_rabbitmq_kali_import.id
    volume_size = 50
    volume_type = "gp3"
  }
  tags = {
    Name      = "rabbitmq-kali-live-os-ami"
    CMIR_ID   = "img-live-rabbitmq-kali"
    ManagedBy = "CloudMove"
  }
}

# Migrated Resource: rabbitmq-kali-live-os-vm (vm-rabbitmq-kali-live-os)
resource "aws_instance" "vm_rabbitmq_kali_live_os" {
  ami                         = var.ami_id != "" ? var.ami_id : aws_ami.img_live_rabbitmq_kali.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_subnet.id
  vpc_security_group_ids      = [aws_security_group.app_sg.id]
  associate_public_ip_address = true
  tags = {
    Name      = "rabbitmq-kali-live-os-vm"
    CMIR_ID   = "vm-rabbitmq-kali-live-os"
    ManagedBy = "CloudMove"
  }
}

# Migrated Resource: rabbitmq-kali-live-os-disk-1 (disk-rabbitmq-kali-live-os-1)
resource "aws_ebs_volume" "disk_rabbitmq_kali_live_os_1" {
  availability_zone = "${var.aws_region}a"
  size              = 50
  type              = "gp3"
  tags = {
    Name      = "rabbitmq-kali-live-os-disk-1"
    CMIR_ID   = "disk-rabbitmq-kali-live-os-1"
    ManagedBy = "CloudMove"
  }
}

